import{_ as o,o as t,c as a,a5 as d}from"./chunks/framework.BYXPg_yw.js";const n="/RBQ/nightly/images/app/home-sound.pc.en.png",r="/RBQ/nightly/images/app/media-audio.pc.en.png",i="/RBQ/nightly/images/app/media-sound.pc.en.png",b=JSON.parse('{"title":"Media","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/media.md","filePath":"manual/gui/media.md","lastUpdated":1792759058000}'),c={name:"manual/gui/media.md"};function s(h,e,l,p,u,m){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="media" tabindex="-1">Media <a class="header-anchor" href="#media" aria-label="Permalink to &quot;Media&quot;">​</a></h1><p>Take photos and record video from the robot&#39;s cameras, record sound, and play sounds through the robot&#39;s speaker. Every file is stored on the robot; the app lists them, plays them, and downloads them.</p><h2 id="control-home" tabindex="-1">On the control home <a class="header-anchor" href="#control-home" aria-label="Permalink to &quot;On the control home {#control-home}&quot;">​</a></h2><p>Two buttons sit to the left of the <code>Talk</code> button in the lower-right corner of the control home. On a narrow screen they stack above <code>Talk</code>.</p><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><code>Sounds</code></td><td>Opens a sound list. Tap one and the robot <strong>plays it on a loop</strong>; tap it again or tap <code>Stop</code> to end it. A green dot on the button means a sound is playing. The robot stops on its own when every app disconnects or after 30 minutes.</td></tr><tr><td><code>Capture</code></td><td>Opens a choice between <code>Photo</code> and <code>Record</code>. <code>Photo</code> saves front and rear camera photos; <code>Record</code> starts a video recording. While it records the button turns red and shows the elapsed time; tap it to save.</td></tr></tbody></table><p>A notice at the bottom of the screen reports each photo and recording.</p><p><img src="'+n+'" alt="Sounds popover"></p><p>The <code>Sounds</code> list holds the built-in sounds, the sounds you uploaded (<code>My sounds</code>), and your eight latest recordings (<code>Recent recordings</code>). Tap <code>List</code> at its top right to see everything on the media screen.</p><h2 id="opening-the-media-screen" tabindex="-1">Opening the media screen <a class="header-anchor" href="#opening-the-media-screen" aria-label="Permalink to &quot;Opening the media screen&quot;">​</a></h2><p>Tap the <code>Media</code> tile on the hub. It opens only while a robot is connected. Pick <code>Photo</code>, <code>Record</code>, <code>Black box</code>, <code>Recording</code>, or <code>Sounds</code> from the list on the left. On a narrow screen such as a phone the list becomes tabs along the top. A red dot on an item means a recording is running there.</p><h2 id="photos" tabindex="-1">Photos <a class="header-anchor" href="#photos" aria-label="Permalink to &quot;Photos&quot;">​</a></h2><p>Tap <code>Take photo</code> to save front and rear camera photos together. Each shot is one card, grouped by day with the newest on top. Tap a card to view it large, and <code>Download</code> to save it on this device.</p><h2 id="recordings-video" tabindex="-1">Recordings (video) <a class="header-anchor" href="#recordings-video" aria-label="Permalink to &quot;Recordings (video)&quot;">​</a></h2><p>Tap <code>Start recording</code> to record the front and rear cameras together, at 5 frames per second for up to 30 minutes. Tap again to save; the front and rear cameras each leave one file. This is the same as <code>Record</code> under <code>Capture</code> on the control home.</p><p>In the list, the front and rear files of one recording share a row. Tap <code>Front</code> or <code>Rear</code> to watch, and switch cameras at the top while watching. Download saves both files.</p><h2 id="black-box" tabindex="-1">Black box <a class="header-anchor" href="#black-box" aria-label="Permalink to &quot;Black box&quot;">​</a></h2><p>Black box continuous recordings. Pick <code>Play</code> or <code>Files</code> at the top.</p><p><code>Play</code> finds a moment by time. The robot plays the recording itself and sends only the picture to the app, so nothing is downloaded and it starts right away.</p><ul><li>Choose the day with <code>Date</code> and the camera with <code>Front</code> / <code>Rear</code>.</li><li><code>Recorded</code> lists each stretch that camera recorded, with its start, end, and length — for example <code>12:26:50 – 13:11:29 (44m)</code>. Each time the robot or its software restarts, a new stretch begins. Tap one to play it from the start.</li><li>The bar shows the shaded recorded stretches. <code>Fit</code> (the default) spans that day&#39;s recordings; <code>24 h</code>, <code>1 h</code>, and <code>10 min</code> zoom around the playback position and follow it. Tap a time on the bar to play from there; if nothing was recorded then, playback starts at the next recording.</li><li><code>Play</code> / <code>Pause</code>, <code>-5m</code> <code>-30s</code> <code>+30s</code> <code>+5m</code> to step, and the speed buttons <code>0.5x</code> to <code>8x</code>. The time shown is the robot&#39;s local time.</li><li>Switching camera keeps the same moment. Playback stops at the end of each recorded stretch and shows when the next one starts; press <code>Play</code> to continue from there.</li><li>Near the present, the newest footage reaches the app a few seconds late. Playback waits for it and carries on.</li><li><code>Stop replay</code> returns the app&#39;s video to live. Leaving the section does the same, and if the app stops responding the robot switches back to live by itself after a few seconds. Other devices watching the robot keep their live video throughout.</li><li>Up to two devices can play recordings from one robot at the same time. Only one of them can be <a href="/RBQ/nightly/manual/gui/emergency.html#spectating">spectating</a>, so the device in control can always play.</li><li>Continuous recording is off by default on the robot. While it is off, the screen says so, and only footage recorded earlier can be played.</li></ul><p><code>Files</code> lists the 30-minute files. Tap a file to play or download it.</p><h2 id="recording" tabindex="-1">Sound recordings <a class="header-anchor" href="#recording" aria-label="Permalink to &quot;Sound recordings {#recording}&quot;">​</a></h2><p>There are two kinds of sound recording. Choose one before you start.</p><table tabindex="0"><thead><tr><th>Choice</th><th>What it captures</th></tr></thead><tbody><tr><td><code>My mic</code></td><td>What this device&#39;s microphone hears while the recording runs. You don&#39;t need to hold <code>Talk</code>, and nothing plays on the robot speaker while recording. Record an announcement ahead of time and play it on a loop through the robot&#39;s speaker.</td></tr><tr><td><code>Robot mic</code></td><td>What the robot&#39;s microphone hears.</td></tr></tbody></table><p>If the robot has no microphone device, the choice does not appear and you record with <code>My mic</code> only. The robot briefly listens to its microphone input when it starts, and once a minute while you are on an audio screen. If it hears almost nothing, <code>The robot mic is picking up almost nothing — check that a microphone is plugged in</code> appears. This is only a notice — listening and recording still work.</p><p>If a recording turns out almost silent, a notice appears when you stop it. For <code>Robot mic</code> it reads <code>That recording is almost silent — check that a microphone is plugged into the robot</code>: the robot&#39;s audio board records even with no microphone plugged in, so this notice is how you find out. For <code>My mic</code> it reads <code>That recording is almost silent — check that this device&#39;s mic is on</code>.</p><p><img src="'+r+'" alt="Recording"></p><p>Tap <code>Play on robot</code> in the list to play a recording through the robot&#39;s speaker. Switch on <code>Loop playback</code> to repeat it until you stop it. You can also start a recording from the audio popover (<a href="/RBQ/nightly/manual/gui/audio.html#recording">Audio</a>).</p><h2 id="delete" tabindex="-1">Deleting <a class="header-anchor" href="#delete" aria-label="Permalink to &quot;Deleting {#delete}&quot;">​</a></h2><p>You can delete files from the robot under <code>Photo</code>, <code>Record</code>, <code>Black box</code> (in <code>Files</code>), <code>Recording</code>, and <code>My sounds</code>. Tap the trash can (<code>Delete files</code>) at the top right of a section to start selecting. Tap the items to delete, tap <code>Delete</code>, then tap <code>Delete</code> again to confirm. To delete everything, tap <code>Select all</code> and then <code>Delete</code>. Tap <code>Cancel</code> to leave selection.</p><p>A photo or recording keeps its front and rear files as one item, so both are deleted together. Files that are still being recorded are skipped, and the app tells you how many were skipped. Deleted files cannot be recovered.</p><h2 id="sounds" tabindex="-1">Sounds <a class="header-anchor" href="#sounds" aria-label="Permalink to &quot;Sounds&quot;">​</a></h2><p><img src="'+i+'" alt="Sounds"></p><p>Built-in sounds grouped into alarms and sirens, chimes, animals, and other. Tap one to play it on the robot. A sound you play for the first time is uploaded to the robot first, so it takes a moment. Switch on <code>Loop playback</code> to repeat it until you stop it.</p><p>Under <code>My sounds</code>, <code>Upload file</code> puts a sound file from this device (mp3, wav and so on, up to 10 MB) on the robot so you can play it any time.</p><p>Sound goes where audio goes: through the PTZ speaker when a PTZ camera is fitted (<a href="/RBQ/nightly/manual/gui/audio.html#output">Where the sound goes</a>).</p>',35)])])}const f=o(c,[["render",s]]);export{b as __pageData,f as default};
